package env

// patches_test.go — services.<name>.patches in the Tilt overlay. The bash
// twin (env::generate_patches) is held to the same output by the parity
// harness (hack/parity-loop.sh), which also renders the overlay through
// kustomize.

import (
	"bytes"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/kernpilot/lok8s/internal/testutil"
)

const patchesArtifact = `apiVersion: apps/v1
kind: Deployment
metadata:
  name: web.app
  namespace: ns1
  labels:
    lok8s.dev/name: web
---
apiVersion: v1
kind: Service
metadata:
  name: web
  namespace: ns1
  labels:
    lok8s.dev/name: web
---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: api
  namespace: ns1
  labels:
    lok8s.dev/name: api
---
- not
- a mapping
`

// patchesCtx is kustomizationCtx with the patches artifact.
func patchesCtx(t *testing.T, merged string) (*Context, string, *bytes.Buffer) {
	t.Helper()
	c, domainDir := kustomizationCtx(t, merged)
	testutil.WriteFile(t, filepath.Join(domainDir, "artifacts.yaml"), patchesArtifact)
	return c, domainDir, c.ErrOut.(*bytes.Buffer)
}

// A config without patches writes the overlay exactly as before the
// feature: no patches block, nothing else moved.
func TestKustomizationWithoutPatchesIsUnchanged(t *testing.T) {
	c, domainDir := kustomizationCtx(t, kustomizationFixture)
	if err := c.Kustomization(t.Context(), true, false); err != nil {
		t.Fatal(err)
	}
	raw, err := os.ReadFile(filepath.Join(domainDir, "artifacts", "kustomization.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	const want = `# Auto-generated by lok8s — do not edit. Source: lo env kustomization.
apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization

resources:
  - ../artifacts.yaml

images:
  - name: lok8s.local/worker
    newName: lok8s.cache/test-project/worker
    newTag: "latest"
  - name: lok8s.local/pinned
    newName: ghcr.io/external/pinned
    newTag: "v1.2.3"
`
	if string(raw) != want {
		t.Errorf("overlay changed without patches:\n%s", raw)
	}
}

func TestKustomizationEmitsPatches(t *testing.T) {
	c, domainDir, errOut := patchesCtx(t, `services:
  web:
    patches:
      - target: {name: web.app, kind: Deployment, group: apps}
        patch: |
          - op: add
            path: /metadata/annotations
            value: {patched: "yes"}
      - target: {version: v1, kind: Service, name: web, namespace: ns1}
        patch: |2
            # an indented first line
          - op: add

          # the end
  api:
    enabled: false
    patches:
      - target: {kind: Deployment, name: not-checked}
        patch: x
  web_:
    patches: []
`)
	if err := c.Kustomization(t.Context(), true, false); err != nil {
		t.Fatalf("%v: %s", err, errOut)
	}
	raw, _ := os.ReadFile(filepath.Join(domainDir, "artifacts", "kustomization.yaml"))
	// The target fields in a fixed order, single-quoted, dots escaped; the
	// label selector last; the patch with its trailing newline removed and
	// its first line's indentation kept.
	const want = `
patches:
  - target:
      group: 'apps'
      kind: 'Deployment'
      name: 'web\.app'
      labelSelector: 'lok8s.dev/name=web'
    patch: |2-
      - op: add
        path: /metadata/annotations
        value: {patched: "yes"}
  - target:
      version: 'v1'
      kind: 'Service'
      name: 'web'
      namespace: 'ns1'
      labelSelector: 'lok8s.dev/name=web'
    patch: |2-
        # an indented first line
      - op: add

      # the end
`
	if !strings.HasSuffix(string(raw), want) {
		t.Errorf("patches block:\n%s", raw)
	}
	if strings.Contains(string(raw), "not-checked") {
		t.Errorf("a disabled service's patch was emitted:\n%s", raw)
	}
}

func TestKustomizationPatchErrors(t *testing.T) {
	for _, tc := range []struct {
		name, patches, want string
	}{
		{"not a list", `patches: {kind: Deployment}`,
			"services.web.patches must be a list"},
		{"entry not a mapping", "patches:\n      - just a string",
			"services.web.patches[0] must be a mapping with 'patch' and 'target'"},
		{"unknown entry key", "patches:\n      - {target: {kind: Deployment, name: web.app}, patch: x, path: p.yaml}",
			"services.web.patches[0].path unknown (allowed: patch, target)"},
		{"patch not a string", "patches:\n      - {target: {kind: Deployment, name: web.app}, patch: {op: add}}",
			"services.web.patches[0].patch must be a non-empty string"},
		{"patch only newlines", "patches:\n      - {target: {kind: Deployment, name: web.app}, patch: \"\\n\\n\"}",
			"services.web.patches[0].patch must be a non-empty string"},
		{"patch control character", "patches:\n      - {target: {kind: Deployment, name: web.app}, patch: \"a\\rb\"}",
			"services.web.patches[0].patch contains a character the overlay cannot carry (only printable characters, tab and newline are allowed)"},
		{"patch line separator", "patches:\n      - {target: {kind: Deployment, name: web.app}, patch: \"a\\u2028b\"}",
			"services.web.patches[0].patch contains a character the overlay cannot carry (only printable characters, tab and newline are allowed)"},
		{"patch next line", "patches:\n      - {target: {kind: Deployment, name: web.app}, patch: \"a\\x85b\"}",
			"services.web.patches[0].patch contains a character the overlay cannot carry (only printable characters, tab and newline are allowed)"},
		{"patch paragraph separator", "patches:\n      - {target: {kind: Deployment, name: web.app}, patch: \"a\\u2029b\"}",
			"services.web.patches[0].patch contains a character the overlay cannot carry (only printable characters, tab and newline are allowed)"},
		{"patch byte-order mark", "patches:\n      - {target: {kind: Deployment, name: web.app}, patch: \"a\\ufeffb\"}",
			"services.web.patches[0].patch contains a character the overlay cannot carry (only printable characters, tab and newline are allowed)"},
		{"patch noncharacter", "patches:\n      - {target: {kind: Deployment, name: web.app}, patch: \"a\\ufffeb\"}",
			"services.web.patches[0].patch contains a character the overlay cannot carry (only printable characters, tab and newline are allowed)"},
		{"patch DEL", "patches:\n      - {target: {kind: Deployment, name: web.app}, patch: \"a\\x7fb\"}",
			"services.web.patches[0].patch contains a character the overlay cannot carry (only printable characters, tab and newline are allowed)"},
		{"patch NUL", "patches:\n      - {target: {kind: Deployment, name: web.app}, patch: \"a\\0b\"}",
			"services.web.patches[0].patch contains a character the overlay cannot carry (only printable characters, tab and newline are allowed)"},
		{"patch only whitespace", "patches:\n      - {target: {kind: Deployment, name: web.app}, patch: \"  \\t\\n \"}",
			"services.web.patches[0].patch must be a non-empty string"},
		{"target value with a trailing newline", "patches:\n      - {target: {kind: Deployment, name: \"web.app\\n\"}, patch: x}",
			"services.web.patches[0].target.name must match [A-Za-z0-9.:-]+"},
		{"target missing", "patches:\n      - {patch: x}",
			"services.web.patches[0].target must be a mapping"},
		{"unknown target key", "patches:\n      - {target: {kind: Deployment, name: web.app, labelSelector: a=b}, patch: x}",
			"services.web.patches[0].target.labelSelector unknown (allowed: group, version, kind, name, namespace)"},
		{"kind missing", "patches:\n      - {target: {name: web.app}, patch: x}",
			"services.web.patches[0].target.kind and services.web.patches[0].target.name are required"},
		{"name null", "patches:\n      - {target: {kind: Deployment, name: null}, patch: x}",
			"services.web.patches[0].target.kind and services.web.patches[0].target.name are required"},
		{"regex in name", "patches:\n      - {target: {kind: Deployment, name: \"web.*\"}, patch: x}",
			"services.web.patches[0].target.name must match [A-Za-z0-9.:-]+"},
		{"null optional field", "patches:\n      - {target: {kind: Deployment, name: web.app, namespace: ~}, patch: x}",
			"services.web.patches[0].target.namespace must match [A-Za-z0-9.:-]+"},
		{"no match", "patches:\n      - {target: {kind: Deployment, name: webXapp}, patch: x}",
			"services.web.patches[0]: target Deployment/webXapp matches no object labelled lok8s.dev/name=web in the test.example artifacts"},
		{"other service's object", "patches:\n      - {target: {kind: Deployment, name: api}, patch: x}",
			"services.web.patches[0]: target Deployment/api matches no object labelled lok8s.dev/name=web in the test.example artifacts"},
		{"wrong group", "patches:\n      - {target: {kind: Deployment, name: web.app, group: batch}, patch: x}",
			"services.web.patches[0]: target Deployment/web.app matches no object labelled lok8s.dev/name=web in the test.example artifacts"},
		{"core object has no group", "patches:\n      - {target: {kind: Service, name: web, group: v1}, patch: x}",
			"services.web.patches[0]: target Service/web matches no object labelled lok8s.dev/name=web in the test.example artifacts"},
		{"wrong version", "patches:\n      - {target: {kind: Service, name: web, version: v2}, patch: x}",
			"services.web.patches[0]: target Service/web matches no object labelled lok8s.dev/name=web in the test.example artifacts"},
		{"wrong namespace", "patches:\n      - {target: {kind: Deployment, name: web.app, namespace: ns2}, patch: x}",
			"services.web.patches[0]: target Deployment/web.app matches no object labelled lok8s.dev/name=web in the test.example artifacts"},
		{"second patch fails", "patches:\n      - {target: {kind: Deployment, name: web.app}, patch: x}\n      - {target: {kind: Deployment, name: gone}, patch: x}",
			"services.web.patches[1]: target Deployment/gone matches no object labelled lok8s.dev/name=web in the test.example artifacts"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			c, domainDir, errOut := patchesCtx(t, "services:\n  web:\n    "+tc.patches+"\n")
			err := c.Kustomization(t.Context(), true, false)
			if !errors.Is(err, ErrHandled) {
				t.Fatalf("err = %v, want ErrHandled", err)
			}
			if got := errOut.String(); got != "[error] "+tc.want+"\n" {
				t.Errorf("stderr = %q\nwant      %q", got, "[error] "+tc.want+"\n")
			}
			// Nothing is written on a failed run.
			for _, f := range []string{"kustomization.yaml", ".cache-queue"} {
				if _, err := os.Stat(filepath.Join(domainDir, "artifacts", f)); err == nil {
					t.Errorf("%s written on a failed run", f)
				}
			}
		})
	}
}

func TestKustomizationPatchServiceNameMustBeALabelValue(t *testing.T) {
	c, _, errOut := patchesCtx(t, "services:\n  web_:\n    patches:\n      - {target: {kind: Deployment, name: web.app}, patch: x}\n")
	if err := c.Kustomization(t.Context(), true, false); !errors.Is(err, ErrHandled) {
		t.Fatalf("err = %v, want ErrHandled", err)
	}
	if want := "[error] services.web_: a service with patches needs a name that is a valid label value\n"; errOut.String() != want {
		t.Errorf("stderr = %q", errOut)
	}
}

// Without a domain artifact no object can match: the patch fails, it is not
// dropped.
func TestKustomizationPatchWithoutDomainArtifactFails(t *testing.T) {
	c, domainDir, errOut := patchesCtx(t, "services:\n  web:\n    patches:\n      - {target: {kind: Deployment, name: web.app}, patch: x}\n")
	os.Remove(filepath.Join(domainDir, "artifacts.yaml"))
	if err := c.Kustomization(t.Context(), true, false); !errors.Is(err, ErrHandled) {
		t.Fatalf("err = %v, want ErrHandled", err)
	}
	if !strings.Contains(errOut.String(), "matches no object labelled lok8s.dev/name=web in the test.example artifacts") {
		t.Errorf("stderr = %q", errOut)
	}
}

func TestKustomizationPatchUnreadableArtifactFails(t *testing.T) {
	c, domainDir, errOut := patchesCtx(t, "services:\n  web:\n    patches:\n      - {target: {kind: Deployment, name: web.app}, patch: x}\n")
	testutil.WriteFile(t, filepath.Join(domainDir, "artifacts.yaml"), "a: [unclosed\n")
	if err := c.Kustomization(t.Context(), true, false); !errors.Is(err, ErrHandled) {
		t.Fatalf("err = %v, want ErrHandled", err)
	}
	if want := "[error] cannot read the test.example artifacts\n"; errOut.String() != want {
		t.Errorf("stderr = %q", errOut)
	}
}

// kustomize matches a target namespace against the effective namespace: an
// object without one is in "default". A colon (RBAC names) is a plain
// character in a target value.
func TestKustomizationPatchDefaultNamespaceAndColon(t *testing.T) {
	c, domainDir, errOut := patchesCtx(t, `services:
  web:
    patches:
      - target: {kind: Deployment, name: nons, namespace: default}
        patch: x
      - target: {kind: ClusterRole, name: "system:web"}
        patch: y
`)
	testutil.WriteFile(t, filepath.Join(domainDir, "artifacts.yaml"), patchesArtifact+`---
apiVersion: apps/v1
kind: Deployment
metadata:
  name: nons
  labels:
    lok8s.dev/name: web
---
apiVersion: rbac.authorization.k8s.io/v1
kind: ClusterRole
metadata:
  name: system:web
  labels:
    lok8s.dev/name: web
`)
	if err := c.Kustomization(t.Context(), true, false); err != nil {
		t.Fatalf("%v: %s", err, errOut)
	}
	raw, _ := os.ReadFile(filepath.Join(domainDir, "artifacts", "kustomization.yaml"))
	for _, want := range []string{"      name: 'nons'\n      namespace: 'default'\n", "      name: 'system:web'\n"} {
		if !strings.Contains(string(raw), want) {
			t.Errorf("overlay misses %q:\n%s", want, raw)
		}
	}
}

// A namespace other than "default" does not match an object without one.
func TestKustomizationPatchOtherNamespaceDoesNotMatchUnset(t *testing.T) {
	c, domainDir, errOut := patchesCtx(t, "services:\n  web:\n    patches:\n      - {target: {kind: Deployment, name: nons, namespace: ns1}, patch: x}\n")
	testutil.WriteFile(t, filepath.Join(domainDir, "artifacts.yaml"), "apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: nons\n  labels:\n    lok8s.dev/name: web\n")
	if err := c.Kustomization(t.Context(), true, false); !errors.Is(err, ErrHandled) {
		t.Fatalf("err = %v, want ErrHandled", err)
	}
	if !strings.Contains(errOut.String(), "target Deployment/nons matches no object") {
		t.Errorf("stderr = %q", errOut)
	}
}

// A malformed services entry (not a mapping) has no patches: the run goes on.
func TestKustomizationPatchesSkipANonMappingService(t *testing.T) {
	c, domainDir, errOut := patchesCtx(t, "services:\n  web: just-a-string\n")
	if err := c.Kustomization(t.Context(), true, false); err != nil {
		t.Fatalf("%v: %s", err, errOut)
	}
	raw, _ := os.ReadFile(filepath.Join(domainDir, "artifacts", "kustomization.yaml"))
	if strings.Contains(string(raw), "patches:") {
		t.Errorf("overlay has patches:\n%s", raw)
	}
}
